    "question": "Two simple graphs G₁ and G₂ are isomorphic. Which of the following quantities must be identical for both graphs?",
    "options": {
      "A": "Number of vertices only.",
      "B": "Number of edges only.",
      "C": "Degree sequence only.",
      "D": "Number of vertices, number of edges, and degree sequence."
    },
    "correct_answer": "D",
    "explanation": "Isomorphic graphs preserve all structural invariants: they have the same vertex count, edge count, and identical degree sequences (up to ordering). Any invariant that differs would prevent an isomorphism.",
    "difficulty": "Medium"
  }
